-- Reassess every Depth Jump source and replace the ambiguous legacy baseline
-- with exact research-authored countermovement vertical-rebound variants.
-- Human media, graph, calibration, content, and publication approvals remain
-- quarantined and are never inferred by this migration.

DO $$
DECLARE
  migration_key CONSTANT TEXT := '463_coaching_depth_jump_family_audit_hardening';
  research_version CONSTANT TEXT := '2026-08-02.75';
  canonical_id UUID;
  source_ids CONSTANT BIGINT[] := ARRAY[3,725,1092];
  source_variant_ids UUID[];
  hips_variant UUID := gen_random_uuid();
  free_arms_variant UUID := gen_random_uuid();
  active_variant_ids UUID[];
  drop_jump_variant UUID;
  drop_landing_variant UUID;
  countermovement_jump_variant UUID;
  current_video_ids CONSTANT TEXT[] := ARRAY['AzPJZHOmGEg','GeN0S3XCZnM','DxzbXy0lC6Y','Phf_HO1w9BA','dGQRsuI_-ag'];
  protected_count INTEGER;
BEGIN
  SELECT definition_id INTO canonical_id FROM coaching.exercise_definition_source_v1 WHERE legacy_exercise_id=3;
  SELECT variant.id INTO drop_jump_variant FROM coaching.exercise_variant_v1 variant JOIN coaching.exercise_definition_v1 definition ON definition.id=variant.definition_id WHERE definition.slug='drop-jump' AND variant.variant_key='baseline';
  SELECT variant.id INTO drop_landing_variant FROM coaching.exercise_variant_v1 variant JOIN coaching.exercise_definition_v1 definition ON definition.id=variant.definition_id WHERE definition.slug='drop-landing-to-stick' AND variant.variant_key='baseline';
  SELECT variant.id INTO countermovement_jump_variant FROM coaching.exercise_variant_v1 variant JOIN coaching.exercise_definition_v1 definition ON definition.id=variant.definition_id WHERE definition.slug='countermovement-jump' AND variant.variant_key='baseline';
  source_variant_ids := ARRAY[
    (SELECT id FROM coaching.exercise_variant_v1 WHERE definition_id=canonical_id AND variant_key='baseline'),
    (SELECT id FROM coaching.exercise_variant_v1 WHERE definition_id=canonical_id AND variant_key='baseline-source-725'),
    (SELECT id FROM coaching.exercise_variant_v1 WHERE definition_id=canonical_id AND variant_key='baseline-source-1092')];
  active_variant_ids := ARRAY[hips_variant,free_arms_variant];
  IF NOT EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 WHERE id=canonical_id AND slug='depth-jump')
    OR (SELECT count(*) FROM coaching.exercise_definition_source_v1 WHERE definition_id=canonical_id AND legacy_exercise_id=ANY(source_ids))<>3
    OR (SELECT count(*) FROM coaching.exercise_variant_v1 WHERE id=ANY(source_variant_ids) AND definition_id=canonical_id)<>3
    OR NOT EXISTS(SELECT 1 FROM coaching.exercise_variant_v1 v JOIN coaching.exercise_definition_v1 d ON d.id=v.definition_id WHERE v.id=drop_jump_variant AND d.slug='drop-jump')
    OR NOT EXISTS(SELECT 1 FROM coaching.exercise_variant_v1 v JOIN coaching.exercise_definition_v1 d ON d.id=v.definition_id WHERE v.id=drop_landing_variant AND d.slug='drop-landing-to-stick')
    OR NOT EXISTS(SELECT 1 FROM coaching.exercise_variant_v1 v JOIN coaching.exercise_definition_v1 d ON d.id=v.definition_id WHERE v.id=countermovement_jump_variant AND d.slug='countermovement-jump') THEN
    RAISE EXCEPTION '% prerequisite identity state is missing or drifted',migration_key;
  END IF;
  IF EXISTS(SELECT 1 FROM coaching.exercise_variant_v1 WHERE id=ANY(active_variant_ids) AND definition_id<>canonical_id) THEN
    RAISE EXCEPTION '% working variant UUID is already owned by another definition',migration_key;
  END IF;

  SELECT COALESCE(sum(n),0) INTO protected_count FROM (
    SELECT count(*) n FROM coaching.exercise_definition_v1 WHERE id=canonical_id AND (reviewed_by IS NOT NULL OR approved_by IS NOT NULL OR last_reviewed_at IS NOT NULL)
    UNION ALL SELECT count(*) FROM coaching.exercise_section_evidence_v1 WHERE definition_id=canonical_id AND reviewer_user_id IS NOT NULL
    UNION ALL SELECT count(*) FROM coaching.exercise_media_candidate_v1 WHERE definition_id=canonical_id AND (reviewer_user_id IS NOT NULL OR reviewed_at IS NOT NULL OR review_status IN('approved'))
    UNION ALL SELECT count(*) FROM coaching.exercise_alternate_assessment_v1 WHERE definition_id=canonical_id AND reviewer_user_id IS NOT NULL
    UNION ALL SELECT count(*) FROM coaching.exercise_delivery_profile_v1 WHERE variant_id=ANY(source_variant_ids||active_variant_ids) AND status IN('approved')
    UNION ALL SELECT count(*) FROM coaching.exercise_relationship_v1 WHERE (from_variant_id=ANY(source_variant_ids||active_variant_ids) OR to_variant_id=ANY(source_variant_ids||active_variant_ids)) AND (reviewed_by IS NOT NULL OR review_status IN('approved'))
    UNION ALL SELECT count(*) FROM coaching.exercise_score_calibration_v1 WHERE variant_id=ANY(source_variant_ids||active_variant_ids) AND (reviewed_by IS NOT NULL OR status='approved')
  ) protected;
  IF protected_count<>0 THEN RAISE EXCEPTION '% refuses to replace human review',migration_key; END IF;

  UPDATE coaching.exercise_section_evidence_v1 SET review_status='superseded',updated_at=now()
  WHERE definition_id=canonical_id AND review_status='candidate' AND reviewer_user_id IS NULL;
  UPDATE coaching.exercise_media_candidate_v1 SET review_status='superseded',updated_at=now()
  WHERE definition_id=canonical_id AND review_status='candidate' AND reviewer_user_id IS NULL;
  UPDATE coaching.exercise_alternate_assessment_v1 SET review_status='superseded',updated_at=now()
  WHERE definition_id=canonical_id AND review_status='candidate' AND reviewer_user_id IS NULL;

  DELETE FROM coaching.exercise_relationship_v1
  WHERE (from_variant_id=ANY(source_variant_ids||active_variant_ids) OR to_variant_id=ANY(source_variant_ids||active_variant_ids))
    AND reviewed_by IS NULL AND review_status<>'approved';
  DELETE FROM coaching.exercise_score_calibration_v1
  WHERE variant_id=ANY(source_variant_ids||active_variant_ids) AND reviewed_by IS NULL AND status<>'approved';

  UPDATE coaching.exercise_definition_source_v1 SET
    source_kind=CASE WHEN legacy_exercise_id=3 THEN 'legacy_migration' ELSE 'duplicate_consolidation' END,
    provenance_json=coalesce(provenance_json,'{}'::JSONB)||jsonb_build_object(
      'migration',migration_key,'sourceDisposition','identity_quarantine','representedBySelectableSourceVariant',FALSE,
      'ambiguity','source_does_not_fix_vertical_direction_countermovement_strategy_arm_policy_step_off_lead_platform_height_final_landing_or_dose',
      'authoritativeSourceRecoveryRequired',TRUE,'humanReviewRequired',TRUE,'approvalsCreated',FALSE)
  WHERE definition_id=canonical_id AND legacy_exercise_id=ANY(source_ids);

  UPDATE coaching.exercise_variant_v1 SET
    variant_key='identity-quarantine-source-'||(source_ids[array_position(source_variant_ids,id)])::TEXT,
    display_name='Depth Jump Identity Quarantine — Source '||(source_ids[array_position(source_variant_ids,id)])::TEXT,
    modifier_keys='{}'::TEXT[],difficulty_json='{}'::JSONB,status='archived',
    requirements_json=jsonb_build_object('selectable',FALSE,'representation','identity_quarantine','sourceLegacyExerciseId',source_ids[array_position(source_variant_ids,id)],'archiveReason','source_conflates_or_omits_direction_contact_strategy_arm_policy_entry_platform_final_landing_or_dose','originalAuthoritativeEvidenceRequired',TRUE,'humanReviewRequired',TRUE),
    load_profile_json=jsonb_build_object('selectable',FALSE),fatigue_profile_json=jsonb_build_object('selectable',FALSE),
    programming_profile_json=jsonb_build_object('selectionStatus','identity_quarantine','selectable',FALSE,'publicationQuarantined',TRUE,'neverRestoreFromNameOrMediaMetadata',TRUE),updated_at=now()
  WHERE id=ANY(source_variant_ids);
  UPDATE coaching.exercise_delivery_profile_v1 SET status='archived',updated_at=now() WHERE variant_id=ANY(source_variant_ids);
  UPDATE coaching.exercise_definition_v1 SET status='archived',approved_video_url=NULL,reviewed_by=NULL,approved_by=NULL,last_reviewed_at=NULL,
    provenance_json=coalesce(provenance_json,'{}'::JSONB)||jsonb_build_object('depthJumpAuditHardeningMigration',migration_key,'survivorDefinitionId',canonical_id,'selectable',FALSE,'humanReviewRequired',TRUE,'approvalsCreated',FALSE),updated_at=now()
  WHERE FALSE;

  UPDATE coaching.exercise_definition_v1 SET
    canonical_name='Depth Jump',display_name='Depth Jump',
    aliases=ARRAY['Countermovement Depth Jump','Countermovement Depth Jumps','Depth Jump to Vertical Jump','Depth Jump to Vertical Jumps','Depth Jump to Rebound','Depth Jumps']::TEXT[],
    description='Step from an individualized stable platform without jumping upward, contact the floor with both feet together, use one continuous countermovement without a pause, reverse immediately into a maximal vertical rebound, land the rebound bilaterally under control, hold, and fully reset. Every selectable variant fixes arm policy; platform height and step-off lead are recorded modifiers.',
    family_key='bilateral_countermovement_depth_jump',schema_version='2.0.0',card_version=3,status='review',
    content_confidence=94,scoring_confidence=66,media_confidence=48,
    movement_patterns=ARRAY['jump','land','squat','brace']::TEXT[],
    body_regions=ARRAY['foot','ankle','calf','knee','hamstrings','glutes','hip','pelvis','core','spine']::TEXT[],
    required_equipment=ARRAY['box']::TEXT[],optional_equipment=ARRAY['mat','jump_mat','line_tape','cones']::TEXT[],
    anatomy_json=jsonb_build_object(
      'primaryMuscles',jsonb_build_array('quadriceps','gluteus_maximus','soleus','gastrocnemius'),
      'secondaryMuscles',jsonb_build_array('hamstrings','gluteus_medius','hip_external_rotators','adductors','tibialis_anterior','intrinsic_foot_muscles','abdominal_wall','spinal_stabilizers'),
      'connectiveTissues',jsonb_build_array('Achilles_tendon','patellar_tendon','quadriceps_tendon','plantar_and_lower_limb_supporting_tissues'),
      'joints',jsonb_build_array('foot','ankle','knee','hip','pelvis','lumbosacral_complex','shoulder_girdle_when_free_arms_are_used'),
      'jointActions',jsonb_build_array('platform_step_off','bilateral_ankle_dorsiflexion_control','bilateral_knee_and_hip_flexion_control','continuous_hip_knee_ankle_reversal','ankle_plantarflexion','knee_extension','hip_extension','vertical_flight_control','final_landing_absorption','pelvis_and_trunk_stabilization'),
      'jointActionPhases',jsonb_build_object('entry',jsonb_build_array('declared_lead_leg_step_off_without_upward_jump'),'firstContact',jsonb_build_array('simultaneous_bilateral_contact','one_continuous_countermovement'),'rebound',jsonb_build_array('immediate_hip_knee_ankle_extension','maximal_vertical_projection','declared_arm_action'),'finalLanding',jsonb_build_array('simultaneous_bilateral_contact','lower_limb_absorption','two_second_hold'),'finish',jsonb_build_array('controlled_exit_and_full_reset')),
      'planes',jsonb_build_array('sagittal_primary','frontal_and_transverse_control'),
      'laterality',jsonb_build_object('entry','declared_unilateral_step_off_lead','firstContact','bilateral','rebound','bilateral','finalLanding','bilateral','leadLegIsModifier',TRUE),
      'evidenceLimit','Small technique studies and heterogeneous training trials do not establish one universal platform height, contact time, arm policy, muscle ranking, dose, transfer effect, or safe threshold.'),
    environment_json=jsonb_build_object('surface','level_dry_consistent_high_traction','platform','rated_inspected_stable_non_slip_with_recorded_height_and_clear_edge','clearance',jsonb_build_array('ceiling','step_off','first_contact','vertical_rebound','final_landing','fall_space','return_route'),'traffic','none_through_station','sightlines',jsonb_build_array('side','front_or_rear'),'instrumentation','record_device_make_method_and_settings_when_height_or_contact_time_is used'),
    population_json=jsonb_build_object('defaultPopulation','participants_with_pain_free_drop_landing_bilateral_rebound_control_and_individualized_coach_review','individualizationRequired',TRUE,'prerequisites',jsonb_build_array('pain_free_drop_landing_to_stick','pain_free_bilateral_countermovement_jump_to_controlled_landing','can_step_off_without_jumping','can_use_one_continuous_countermovement_without_pause_or_bounce_strategy','can_report_symptoms_fear_fatigue_and_recovery'),'cautions',jsonb_build_array('pain_giving_way_dizziness_or_apprehension','recent_lower_limb_spine_injury_surgery_or_immobilization','uncontrolled_neurologic_cardiopulmonary_or_balance_condition','pregnancy_or_postpartum_status_requiring_individualization','unsafe_platform_surface_clearance_or_supervision','cannot_control_first_contact_rebound_or_final_landing'),'notClinicalClearance',TRUE,'neverInferReadinessFromExerciseDifficulty',TRUE),
    athlete_support_json=jsonb_build_object('whatItIs','Step off the assigned platform, meet the floor with both feet, use one smooth dip, jump straight up maximally, land on both feet, hold, and reset.','before',jsonb_build_array('Confirm arm policy, platform height, step-off lead, rebound target, attempts, rest, stop signal, and total contact budget.','Check platform, surface, ceiling, landing and fall space, footwear, and traffic.','Report pain, giving way, dizziness, fear, unusual fatigue, or uncertainty before starting.'),'during',jsonb_build_array('Step off without jumping upward.','Meet the floor together and use one continuous countermovement without pausing.','Rebound straight up, land together, hold two seconds, then reset.','Stop before contact strategy, height, symmetry, sound, alignment, or confidence changes.'),'expectedSensations',jsonb_build_array('brief_high_force_lower_body_loading','smooth_countermovement_reversal','maximal_vertical_effort','controlled_final_landing'),'notExpected',jsonb_build_array('sharp_or_increasing_pain','giving_way','dizziness','fear','asymmetrical_contact','pause_or_uncontrolled_collapse'),'selfChecks',jsonb_build_array('correct_platform_lead_and_arm_rule','step_off_without_upward_jump','both_feet_contact_together','one_smooth_dip','vertical_rebound','bilateral_hold_and_full_reset'),'accessibility',jsonb_build_array('lower_platform','fewer_attempts','longer_rest','visible_landing_marks','written_or_still_frame_sequence','drop_landing_to_stick','floor_countermovement_jump','non_impact_power_alternative'),'stopSignal','Stop immediately, secure the station, tell the coach what changed, and do not retry until identity, height, task, symptoms, dose, and recovery are re-evaluated.'),
    coach_support_json=jsonb_build_object('setupChecklist',jsonb_build_array('verify_exact_variant_profile_arm_policy_platform_height_and_step_off_lead','inspect_platform_surface_ceiling_landing_fall_and_return_space','declare_rebound_metric_attempts_hold_reset_rest_contacts_and_stop_threshold','review recent foot_calf_Achilles_knee_hip_sprint_running_jump_lifting_and_sport exposure'),'observeFromSide',jsonb_build_array('true_step_off','first_contact_and_countermovement_continuity','pause_or_bounce_strategy_drift','vertical_rebound_and_height','final_landing_depth_hold_and_reset'),'observeFromFrontOrRear',jsonb_build_array('bilateral_contact_timing','foot_knee_hip_pelvis_and_trunk_control','vertical_vs_horizontal_drift','final_landing_symmetry'),'validRep','Exact platform, lead, arm rule, true step-off, simultaneous bilateral first contact, one continuous countermovement, immediate maximal vertical rebound, simultaneous controlled final landing, two-second hold, and full reset all pass without a stop rule.','correctionOrder',jsonb_build_array('wrong_variant_platform_lead_arm_or_station','symptom_fear_or_incident_stop','jump_from_platform_or_asymmetrical_contact','pause_bounce_strategy_or_excessive_collapse','nonvertical_or_reduced_rebound','final_landing_alignment_hold_or_reset','contact_output_duration_and_recovery_budget'),'groupManagement',jsonb_build_array('one_active_athlete_per_platform_and_landing_zone','next_athlete_waits_outside_fall_and_return_space','coach_controls_platform_changes_and_attempt starts','count_both_landings_for_every_valid_failed_and_incident_attempt'),'escalation','Quarantine selection when identity, station, height, readiness, symptoms, contact budget, supervision, measurement, or media is uncertain.'),
    support_operations_json=jsonb_build_object('selectionInputs',jsonb_build_array('definition_variant_profile_card_and_research_version','objective_phase_and_vertical_rebound_metric','arm_policy_platform_height_step_off_lead_surface_and_measurement_method','attempts_hold_reset_rest_duration_and_two_contacts_per_attempt','recent_foot_calf_Achilles_knee_hip_sprint_running_jump_lifting_and_sport load','symptoms_fear_recovery_population_supervision_and_environment'),'persistence',jsonb_build_array('workout_and_item_id','definition_variant_profile_card_and_research_version','arm_policy_platform_height_step_off_lead_surface_and_measurement_method','sets_valid_failed_and_incident_attempts_and_all_contacts','contact_strategy_contact_time_rebound_height_final_landing_and_hold','rest_faults_symptoms_duration_output_loss_recovery_and_substitution','rendered_athlete_and_coach_instruction_versions'),'incidentPath',jsonb_build_array('call_stop_and_secure_station','assess_immediate_facility_response_without_in_product_diagnosis','record_variant_platform_attempt_contacts_fault_symptom_and_context','follow_emergency_or_clinical_referral_policy','quarantine_uncertain_source_card_or_media'),'changeImpact','Any arm, platform, height, lead, surface, strategy, rebound target, measurement, final landing, dose, fatigue, recovery, population, station, or media change invalidates cached selection, duration, logistics, rendering, and approval assumptions.','publication',jsonb_build_object('humanMediaGraphCalibrationContentAndSeparateApprovalRequired',TRUE)),
    provenance_json=coalesce(provenance_json,'{}'::JSONB)||jsonb_build_object('depthJumpAuditHardeningMigration',migration_key,'researchVersion',research_version,'canonicalAuthoredFromResearch',TRUE,'legacySourcesQuarantined',source_ids,'activeWorkingSpecifications',jsonb_build_array('countermovement-vertical-rebound-hands-on-hips','countermovement-vertical-rebound-free-arms'),'primaryResearchSource','https://pmc.ncbi.nlm.nih.gov/articles/PMC5260527/','methodologyReview','https://pmc.ncbi.nlm.nih.gov/articles/PMC10160442/','identityDecision','platform_step_off_to_bilateral_continuous_countermovement_maximal_vertical_rebound_and_controlled_bilateral_final_landing','mediaState','five_prior_oembed_healthy_candidates_carried_forward_unreviewed','oembedOriginallyCheckedAt','2026-08-02','freshOembedRecheckSucceeded',FALSE,'exerciseDifficultyModel','exercise_complexity_and_physical_difficulty_only','approvalsCreated',FALSE,'publicationQuarantined',TRUE,'humanReviewRequired',TRUE),
    approved_video_url=NULL,reviewed_by=NULL,approved_by=NULL,last_reviewed_at=NULL,updated_at=now()
  WHERE id=canonical_id;

  INSERT INTO coaching.exercise_variant_v1(id,definition_id,variant_key,display_name,modifier_keys,difficulty_json,requirements_json,status,load_profile_json,fatigue_profile_json,programming_profile_json)
  SELECT v.id,canonical_id,v.variant_key,v.display_name,
    ARRAY['platform_height','step_off_lead','surface','rebound_target','attempts','rest_seconds','measurement_method']::TEXT[],
    jsonb_build_object('technicalComplexity',v.complexity,'absoluteLoadDemand',v.physical,'physicalDifficulty',v.physical,'baseOverallDifficulty',GREATEST(v.complexity,v.physical),'coordinationDemand',v.coordination,'supervisionDemand',v.supervision,'failureConsequence',v.failure,'impact',v.impact,'workCapacityDemand',24,'provisional',TRUE,'difficultyModel','max_exercise_complexity_physical_difficulty','technicalMeaning','exercise_complexity','loadMeaning','physical_difficulty','athleteReadinessStoredHere',FALSE),
    jsonb_build_object('actionIdentity','platform_step_off_to_countermovement_vertical_rebound','entry','declared_lead_leg_steps_off_without_upward_jump','firstContact','simultaneous_bilateral','contactStrategy','one_continuous_countermovement_without_pause','armPolicy',v.arm_policy,'rebound','immediate_maximal_vertical','finalLanding','simultaneous_bilateral_controlled_two_second_hold','terminalAction','controlled_exit_and_full_reset','laterality','unilateral_declared_entry_then_bilateral_contact_rebound_and_landing','selectable',TRUE,'identityQuarantine',FALSE,'workingSpecificationRequiresHumanContentReview',TRUE),
    'review',
    jsonb_build_object('gripDemand',1,'externalLoadMethod','bodyweight','externalLoadDescription','No external load; body mass falls from the recorded platform, is reversed into a maximal vertical rebound, and is received again on the floor.','spinalLoading',48,'eccentricStress',84,'landingContactsPerRep',2,'impactClass','high_and_platform_surface_strategy_body_mass_and_output_dependent','loadTracking',jsonb_build_array('body_mass','platform_height','surface_and_footwear','step_off_lead_and_arm_policy','valid_failed_and_incident_attempts','both_landings_per_attempt','contact_strategy_time_and_rebound_height','symptoms_and_recovery'),'effectiveLoadDrivers',jsonb_build_array('body_mass','actual_fall_height','platform_exit','surface','countermovement_depth_and_strategy','maximal_rebound_intent','arm_policy','attempts_and_failed_contacts','recent_running_sprint_jump_lifting_and_sport load')),
    jsonb_build_object('localMuscleFatigue',64,'gripFatigue',1,'technicalFatigueSensitivity',82,'neuralOutputDemand',76,'impactAccumulation',82,'recoveryHours','24_to_96_context_dependent','primaryFatigueSites',jsonb_build_array('foot_calf_and_Achilles','quadriceps_patellar_tendon_and_knee','gluteals_hamstrings_and_hip_stabilizers','trunk_and_landing_control'),'earlyFatigueSignals',jsonb_build_array('hesitant_or_active_platform_exit','asymmetrical_first_contact','pause_or_shallow_bounce_strategy','lower_or_nonvertical_rebound','longer_or_changed_contact','louder_deeper_or_asymmetrical_final_landing'),'downstreamConflicts',jsonb_build_array('priority_sprint_jump_cut_or_reactive work','high_volume_running_or_sport_contacts','heavy_lower_body_eccentric_strength_or_power work','symptomatic_foot_Achilles_knee_hip_or_spine loading')),
    jsonb_build_object('trainingStimuli',jsonb_build_array('high_rate_eccentric_absorption','continuous_countermovement_reversal','maximal_vertical_rebound','bilateral_final_landing_control'),'stimulusDose',jsonb_build_object('primary','fully_reset_maximal_quality_attempts','fatigueCeiling','very_low','landingContactsPerAttempt',2),'weeklyExposure','Combine all valid, failed, and incident landings with same-session running, sprinting, jumping, cutting, lifting, and sport contacts; platform height alone is not intensity.','prerequisites',jsonb_build_array('pain_free_drop_landing_to_stick','pain_free_bilateral_countermovement_jump','exact_strategy_and_arm_rule_understood','platform_station_and_contact_budget_verified'),'completionCriteria',jsonb_build_array('true_step_off_and_bilateral_contact','continuous_countermovement_and_immediate_vertical_rebound','final_landing_hold_and_reset pass','contact_output_symptom_duration_and_recovery_records complete'),'sequenceRules',jsonb_build_array('place_after_specific_preparation_and_before_fatiguing_lower_body_work_when_output_is_priority','use_full_reset_and_long_rest','never_extend_the_set_to_chase_fatigue'),'pairingCompatibility',jsonb_build_array('noncompeting_low_risk_upper_body_mobility_or_breathing_task_during_full_rest'),'interferenceRules',jsonb_build_array('do_not_prefatigue_lower_body_or_trunk_before_priority_attempts','do_not_increase_height_when_strategy_output_landing_or_recovery_changes','recompute_identity_impact_fatigue_duration_logistics_and_rendering_after_substitution'),'uncertaintyPolicy',jsonb_build_object('unknownIdentityStationSymptomsReadinessMeasurementOrRecovery','fail_closed_and_request_coach_review','neverInferMissingSourceMechanics',TRUE,'neverAutoApproveMediaGraphCalibrationOrPublication',TRUE),'cumulativeBudget',jsonb_build_object('landingContactsPerAttempt',2,'countValidFailedAndIncidentContacts',TRUE,'calfAchilles',78,'kneeHipExtensor',80,'technicalSensitivity',82,'sameSessionRunningSprintJumpLiftingAndSportRequired',TRUE))
  FROM (VALUES
    (hips_variant,'countermovement-vertical-rebound-hands-on-hips','Depth Jump — Countermovement Vertical Rebound, Hands on Hips','hands_remain_on_hips_from_platform_setup_through_final_landing'::TEXT,64,72,68,78,84,82),
    (free_arms_variant,'countermovement-vertical-rebound-free-arms','Depth Jump — Countermovement Vertical Rebound, Free Arms','free_coordinated_arm_swing_with_no_external_target_or_support'::TEXT,68,72,74,80,84,82)
  ) v(id,variant_key,display_name,arm_policy,complexity,physical,coordination,supervision,failure,impact)
  ON CONFLICT(id) DO UPDATE SET definition_id=EXCLUDED.definition_id,variant_key=EXCLUDED.variant_key,display_name=EXCLUDED.display_name,modifier_keys=EXCLUDED.modifier_keys,difficulty_json=EXCLUDED.difficulty_json,requirements_json=EXCLUDED.requirements_json,status='review',load_profile_json=EXCLUDED.load_profile_json,fatigue_profile_json=EXCLUDED.fatigue_profile_json,programming_profile_json=EXCLUDED.programming_profile_json,updated_at=now();

  INSERT INTO coaching.exercise_delivery_profile_v1(variant_id,profile_key,phase_key,role,purpose,phase_suitability,methodology_alignment,objective_relevance_json,dosage_json,quality_gate,stop_rules,coach_instructions,athlete_instructions,expected_adaptation,equipment_required,logistics_json,substitution_ids,status,time_model_json,dose_scaling_json,measurement_json,support_prompts_json)
  SELECT p.variant_id,p.profile_key,p.phase,p.role,p.purpose,p.suitability,92,
    jsonb_build_object('verticalPower',p.power,'countermovementStrategy',5,'landingControl',5,'impactManagement',5),
    jsonb_build_object('doseType','fully_reset_quality_attempts','sets',p.sets,'attemptsPerSet',p.attempts,'platformHeight','individualized_recorded_not_an_intensity_proxy','stepOffLead','declared_and_recorded','armPolicy',p.arm_policy,'intent','maximal_vertical_rebound','finalLandingHoldSeconds',2,'resetBetweenAttemptsSeconds',p.reset,'restBetweenSetsSeconds',p.rest,'countValidFailedAndIncidentAttempts',TRUE,'landingContactsPerAttempt',2,'outputLossStopPercent',p.output_loss),
    'Every counted attempt uses the exact platform, lead, and arm rule; steps off without jumping; contacts bilaterally; uses one continuous countermovement; rebounds immediately and vertically within the target band; lands together, holds two seconds, and fully resets.',
    ARRAY['pain_giving_way_dizziness_fear_or_unusual_symptoms','wrong_variant_arm_policy_platform_height_lead_surface_or_measurement','platform_landing_ceiling_fall_return_space_or_traffic_is_unsafe','jump_or_push_upward_from_platform','asymmetrical_or_unexpected_first_contact','pause_shallow_bounce_strategy_or_excessive_collapse','nonvertical_rebound_or_output_loss_exceeds_threshold','loud_valgus_trunk_loss_or_uncontrolled_final_landing','unplanned_extra_contact_or_incomplete_hold_and_reset','contact_impact_duration_or_recovery_budget_exceeded'],
    'Verify the exact variant, arm policy, platform height, step-off lead, surface, rebound metric, attempts, rest, two contacts per attempt, cumulative impact budget, symptoms, recent lower-body work, and station safety. Observe side plus front or rear, count every landing, and lower or replace the task before strategy or output changes.',
    'Use the assigned arms. Step off without jumping, meet the floor together, dip once smoothly, jump straight up maximally, land together, hold, and reset. Stop for pain, fear, a pause, uneven contact, or any changed rep.',
    p.adaptation,ARRAY['box']::TEXT[],
    jsonb_build_object('athletesPerStation',1,'setupSeconds',45,'transitionSeconds',25,'station','one_inspected_platform_with_exclusive_step_off_first_contact_rebound_final_landing_fall_and_return_space','equipmentCheck','rated_stable_non_slip_box_level_consistent_floor_ceiling_and_routes_clear_no_traffic','platformChangeRule','coach_reinspects_and_recomputes_actual_fall_height_strategy_contacts_duration_and risk','substitutionRevalidation',jsonb_build_array('identity','arm_policy','platform_height','lead','surface','strategy','measurement','landing','impact','fatigue','duration','population','rendering')),
    CASE WHEN p.variant_id=hips_variant THEN ARRAY[free_arms_variant,countermovement_jump_variant,drop_landing_variant,drop_jump_variant]::UUID[] ELSE ARRAY[hips_variant,countermovement_jump_variant,drop_landing_variant,drop_jump_variant]::UUID[] END,
    'review',jsonb_build_object('setupSeconds',45,'attemptSeconds',6,'finalLandingHoldSeconds',2,'resetSeconds',p.reset,'durationIncludesRest',TRUE,'durationFormula','setup + sets * (attempts * (attempt + hold + reset) + inter_set_rest) + transition','durationCeilingSeconds',p.ceiling,'recomputeAfterSubstitution',TRUE),
    jsonb_build_object('reduce',jsonb_build_array('lower_platform','reduce_attempts','increase_reset_and_rest','use_hands_on_hips_standardization','use_drop_landing_to_stick','use_floor_countermovement_jump','use_non_impact_power_task'),'increase',jsonb_build_array('increase_rebound_target_within_owned_strategy','add_attempt_within_contact_budget','use_free_arms_variant_if_objective_matches','change_platform_only_after_strategy_landing_output_and_recovery pass'),'revalidateAfterChange',TRUE),
    jsonb_build_object('record',jsonb_build_array('definition_id','variant_id','profile_key','platform_type_height_and_actual_fall_height_if_measured','step_off_lead_arm_policy_surface_and_measurement_method','sets_valid_failed_and_incident_attempts','both_landings_per_attempt','contact_strategy_time_rebound_height_final_landing_and_hold','reset_rest_output_loss_faults_symptoms_duration_and recovery','substitution'),'validity','all exact identity, station, strategy, contact, output, landing, duration, symptom, and recovery gates pass'),
    jsonb_build_object('before','Which exact variant, arm rule, platform, lead, surface, rebound target, measurement, dose, rest, contact budget, and stop signal are assigned?','during','Do step-off, bilateral contact, smooth countermovement, vertical rebound, final landing, symptoms, and output still match?','after','Store both contacts for every attempt, platform and method, strategy, height, landing, faults, symptoms, duration, recovery, and substitution.')
  FROM (VALUES
    (hips_variant,'strategy-standardization','movement_intelligence','secondary','Standardize the hands-on-hips countermovement depth-jump sequence at an individualized lower platform while preserving maximal vertical intent.',88,5,2,2,30,150,8,'More repeatable step-off, continuous countermovement, vertical rebound, final landing, and reset under a fixed arm policy.','hands_on_hips',900),
    (hips_variant,'maximal-height','output','primary','Express maximal vertical rebound from a standardized hands-on-hips countermovement depth jump without strategy drift or fatigue chasing.',94,5,3,2,35,180,6,'Improved high-quality maximal vertical rebound expression under a standardized hands-on-hips protocol.','hands_on_hips',1080),
    (free_arms_variant,'strategy-standardization','movement_intelligence','secondary','Standardize free-arm coordination with the exact step-off, continuous countermovement, vertical rebound, final landing, and reset sequence.',84,5,2,2,35,165,8,'More repeatable whole-body coordination and vertical rebound without changing the countermovement strategy.','free_coordinated',960),
    (free_arms_variant,'maximal-height','output','primary','Express maximal vertical rebound with free coordinated arms while preserving exact entry, strategy, direction, landing, and contact quality.',94,5,3,2,40,210,6,'Improved high-quality maximal vertical rebound expression with coordinated arm contribution.','free_coordinated',1200)
  ) p(variant_id,profile_key,phase,role,purpose,suitability,power,sets,attempts,reset,rest,output_loss,adaptation,arm_policy,ceiling)
  ON CONFLICT(variant_id,profile_key) DO UPDATE SET phase_key=EXCLUDED.phase_key,role=EXCLUDED.role,purpose=EXCLUDED.purpose,phase_suitability=EXCLUDED.phase_suitability,methodology_alignment=EXCLUDED.methodology_alignment,objective_relevance_json=EXCLUDED.objective_relevance_json,dosage_json=EXCLUDED.dosage_json,quality_gate=EXCLUDED.quality_gate,stop_rules=EXCLUDED.stop_rules,coach_instructions=EXCLUDED.coach_instructions,athlete_instructions=EXCLUDED.athlete_instructions,expected_adaptation=EXCLUDED.expected_adaptation,equipment_required=EXCLUDED.equipment_required,logistics_json=EXCLUDED.logistics_json,substitution_ids=EXCLUDED.substitution_ids,status='review',time_model_json=EXCLUDED.time_model_json,dose_scaling_json=EXCLUDED.dose_scaling_json,measurement_json=EXCLUDED.measurement_json,support_prompts_json=EXCLUDED.support_prompts_json,updated_at=now();

  INSERT INTO coaching.exercise_section_evidence_v1(definition_id,reviewed_card_version,section_key,source_url,source_title,source_publisher,source_kind,claims_json,evidence_quality,review_status,reviewer_user_id,reviewed_at)
  SELECT canonical_id,3,e.section_key,e.source_url,e.source_title,e.source_publisher,e.source_kind,
    e.claims_json||jsonb_build_array(jsonb_build_object('migration',migration_key,'researchVersion',research_version,'sourceAudit','all_three_legacy_sources_are_ambiguous_and_nonselectable','workingVariants',jsonb_build_array('hands_on_hips','free_arms'),'limitations','Technique evidence includes a study of eight male youth basketball players and a heterogeneous review of 22 training studies; neither establishes universal height, dose, safety, or transfer.','humanReviewRequired',TRUE,'approvalsCreated',FALSE)),
    e.evidence_quality,'candidate',NULL,NULL
  FROM coaching.exercise_section_evidence_v1 e
  WHERE e.definition_id=canonical_id AND e.reviewed_card_version=2 AND e.section_key IN('identity','taxonomy','anatomy','biomechanics','difficulty','load_fatigue_recovery','constraints','dosage','instructions','safety_stop_rules','programming','athlete_support','coach_support','accessibility','alternates','media')
  ON CONFLICT(definition_id,reviewed_card_version,section_key,source_url) DO UPDATE SET source_title=EXCLUDED.source_title,source_publisher=EXCLUDED.source_publisher,source_kind=EXCLUDED.source_kind,claims_json=EXCLUDED.claims_json,evidence_quality=EXCLUDED.evidence_quality,review_status='candidate',reviewer_user_id=NULL,reviewed_at=NULL,updated_at=now();

  INSERT INTO coaching.exercise_media_candidate_v1(definition_id,variant_id,reviewed_card_version,url,embed_url,video_id,title,channel_name,language_code,captions_available,embedding_allowed,exact_variant_match,demonstration_quality_score,link_status,review_status,discovery_method,source_query,reviewer_user_id,reviewed_at,next_review_at,notes)
  SELECT canonical_id,NULL,3,m.url,m.embed_url,m.video_id,m.title,m.channel_name,'en',NULL,TRUE,NULL,NULL,'healthy','candidate','manual_research',m.source_query,NULL,NULL,'2026-11-02T00:00:00.000Z'::TIMESTAMPTZ,
    'Card-v2 oEmbed link, title, channel, and iframe metadata were recorded healthy on 2026-08-02 and are carried forward. The attempted fresh fetch returned cache misses and is not verification. Full playback, exact hands-on-hips or free-arms match, captions, accessibility, safety, cue quality, conflicts, reviewer identity, and approval remain unresolved.'
  FROM coaching.exercise_media_candidate_v1 m
  WHERE m.definition_id=canonical_id AND m.reviewed_card_version=2 AND m.video_id=ANY(current_video_ids)
  ON CONFLICT(definition_id,reviewed_card_version,video_id) DO UPDATE SET variant_id=NULL,url=EXCLUDED.url,embed_url=EXCLUDED.embed_url,title=EXCLUDED.title,channel_name=EXCLUDED.channel_name,language_code='en',captions_available=NULL,embedding_allowed=TRUE,exact_variant_match=NULL,demonstration_quality_score=NULL,link_status='healthy',review_status='candidate',discovery_method='manual_research',source_query=EXCLUDED.source_query,reviewer_user_id=NULL,reviewed_at=NULL,next_review_at=EXCLUDED.next_review_at,notes=EXCLUDED.notes,updated_at=now();

  INSERT INTO coaching.exercise_alternate_assessment_v1(definition_id,reviewed_card_version,alternate_name,classification,rationale,distinguishing_dimensions,proposed_card_json,review_status,reviewer_user_id,reviewed_at)
  SELECT canonical_id,3,a.name,a.classification,a.rationale,a.dimensions,NULL,'candidate',NULL,NULL
  FROM (VALUES
    ('Source 3 Generic Depth Jump','reject','The source permits vertical or target output and requests minimal contact without fixing countermovement strategy, arm policy, platform, step-off lead, final landing, or dose.',jsonb_build_object('sourceIds',jsonb_build_array(3),'identityQuarantine',TRUE)),
    ('Source 725 Depth Jump to Vertical Jump','reject','The source names vertical output but omits exact platform, lead, arm policy, contact strategy, final landing hold, reset, measurement, and dose.',jsonb_build_object('sourceIds',jsonb_build_array(725),'identityQuarantine',TRUE)),
    ('Source 1092 Depth Jump to Rebound','reject','The source is generic and omits exact direction, platform, lead, arm policy, contact strategy, final landing, reset, and dose.',jsonb_build_object('sourceIds',jsonb_build_array(1092),'identityQuarantine',TRUE)),
    ('Countermovement Vertical Rebound — Hands on Hips','same_identity','This is the standardized baseline: fixed hands-on-hips arm policy, true step-off, bilateral contact, one continuous countermovement, maximal vertical rebound, final landing, hold, and reset.',jsonb_build_object('variantKey','countermovement-vertical-rebound-hands-on-hips')),
    ('Countermovement Vertical Rebound — Free Arms','new_variant','Free coordinated arms change whole-body coordination and attainable rebound while preserving the remaining exact Depth Jump sequence.',jsonb_build_object('variantKey','countermovement-vertical-rebound-free-arms')),
    ('Platform Height','modifier_annotation','Recorded individualized platform height changes fall exposure but is not a standalone intensity or readiness score.',jsonb_build_object('modifier','platform_height')),
    ('Step-Off Lead Leg','modifier_annotation','The lead leg is declared and recorded for entry consistency; first contact, rebound, and final landing remain bilateral.',jsonb_build_object('modifier','step_off_lead')),
    ('Rebound Target Band','modifier_annotation','A recorded vertical target or measured band scales the output criterion without changing direction or contact strategy.',jsonb_build_object('modifier','rebound_target')),
    ('Attempts, Reset, Rest, and Contact Budget','modifier_annotation','These scale dose within one exact platform, lead, arm, strategy, direction, and landing contract.',jsonb_build_object('modifiers',jsonb_build_array('attempts','reset','rest','contact_budget'))),
    ('Contact Time Recorded','modifier_annotation','Contact time may monitor strategy but does not replace maximal vertical rebound as the primary Depth Jump objective.',jsonb_build_object('modifier','contact_time_measurement')),
    ('Force-Plate or Jump-Mat Measurement','modifier_annotation','Measurement method, device, settings, and calculation must be stored; instrumentation does not create a different movement identity.',jsonb_build_object('modifier','measurement_method')),
    ('Bounce Drop Jump','new_definition','Limited flexion and shortest useful contact prioritize reactive strength index rather than maximal countermovement rebound height.',jsonb_build_object('contactStrategy','bounce','targetDefinition','drop-jump')),
    ('Drop Landing to Stick','new_definition','Holding the first landing removes the immediate rebound and changes dose, purpose, and terminal action.',jsonb_build_object('terminalAction','first_contact_hold','targetDefinition','drop-landing')),
    ('Floor Countermovement Jump','new_definition','Removing the platform eliminates passive fall entry and first landing while retaining a vertical countermovement jump.',jsonb_build_object('entry','floor_start','targetDefinition','countermovement-jump')),
    ('Depth Jump to Horizontal Target','new_definition','Horizontal projection changes vector, space, landing location, braking, and measurement and is not an alias for vertical Depth Jump.',jsonb_build_object('reboundDirection','horizontal_or_target')),
    ('Depth Jump to Box','new_definition','Landing the rebound on a second platform adds obstacle clearance, elevated landing, collision, and exit constraints.',jsonb_build_object('finalLandingSurface','second_platform')),
    ('Weighted Depth Jump','new_definition','External load changes fall control, reversal, object management, landing consequence, dose, and recovery.',jsonb_build_object('externalLoad',TRUE)),
    ('Single-Leg First Contact Depth Jump','new_definition','Unilateral first contact changes laterality, loading, balance, side dose, readiness, and failure consequence.',jsonb_build_object('firstContact','unilateral')),
    ('Single-Leg Rebound or Final Landing','new_definition','Unilateral propulsion or terminal support requires side-specific identity, loading, scoring, and stop rules.',jsonb_build_object('reboundOrFinalLanding','unilateral')),
    ('Repeated Depth Rebounds','new_definition','Multiple immediate rebounds remove full reset and create repeated-contact rhythm, fatigue, and contact accounting.',jsonb_build_object('repetitions','continuous_rebounds')),
    ('Lateral Depth Jump','new_definition','Lateral projection changes orientation, vector, frontal-plane demand, station layout, and observation.',jsonb_build_object('reboundDirection','lateral')),
    ('Rotational Depth Jump','new_definition','Planned rotation changes takeoff and landing orientation, balance, visual control, space, and consequence.',jsonb_build_object('rotation',TRUE)),
    ('Unstable-Surface Depth Jump','reject','An unstable first-contact or final-landing surface conflicts with the exact stable high-traction specification and raises uncontrolled risk.',jsonb_build_object('surface','unstable','selectable',FALSE)),
    ('Maximum Rebound-Height Test','new_variant','A formal escalating or repeated assessment changes warm-up, attempts, measurement validity, failure rules, stopping, and result persistence.',jsonb_build_object('purpose','maximum_rebound_height_test'))
  ) a(name,classification,rationale,dimensions)
  ON CONFLICT(definition_id,reviewed_card_version,alternate_name) DO UPDATE SET classification=EXCLUDED.classification,rationale=EXCLUDED.rationale,distinguishing_dimensions=EXCLUDED.distinguishing_dimensions,proposed_card_json=NULL,review_status='candidate',reviewer_user_id=NULL,reviewed_at=NULL,updated_at=now();

  INSERT INTO coaching.exercise_relationship_v1(from_variant_id,to_variant_id,relationship,similarity_score,dimensions,reason,conditions_json,review_status,created_by,reviewed_by,reviewed_at) VALUES
    (hips_variant,free_arms_variant,'lateral_substitution',90,ARRAY['complexity'],'Free coordinated arms change coordination and attainable rebound; platform, lead, target, dose, and measurement must be revalidated.','{"revalidate":["arm_policy","platform_height","rebound_target","dose","measurement","rendering"]}'::JSONB,'review',NULL,NULL,NULL),
    (free_arms_variant,hips_variant,'lateral_substitution',90,ARRAY['complexity'],'Hands-on-hips standardizes arm contribution and changes attainable rebound; platform, target, dose, and measurement must be revalidated.','{"revalidate":["arm_policy","platform_height","rebound_target","dose","measurement","rendering"]}'::JSONB,'review',NULL,NULL,NULL),
    (hips_variant,countermovement_jump_variant,'regression',84,ARRAY['impact','complexity'],'Floor Countermovement Jump removes passive fall entry and the first high-impact landing while preserving bilateral vertical countermovement propulsion.','{"useWhen":["platform_entry_or_two_contact_impact_is_not_appropriate"],"revalidate":["identity","contacts","dose","duration","rendering"]}'::JSONB,'review',NULL,NULL,NULL),
    (free_arms_variant,countermovement_jump_variant,'regression',86,ARRAY['impact','complexity'],'Free-arm Countermovement Jump removes platform entry and first landing while retaining coordinated-arm vertical propulsion.','{"useWhen":["platform_entry_or_two_contact_impact_is_not_appropriate"],"revalidate":["identity","contacts","dose","duration","rendering"]}'::JSONB,'review',NULL,NULL,NULL),
    (hips_variant,drop_landing_variant,'regression',78,ARRAY['impact','complexity'],'Drop Landing to Stick removes the immediate maximal rebound and permits direct observation of first-landing control.','{"useWhen":["rebound_strategy_or_output_is_not_owned"],"revalidate":["identity","terminal_action","contacts","dose","rendering"]}'::JSONB,'review',NULL,NULL,NULL),
    (free_arms_variant,drop_landing_variant,'regression',76,ARRAY['impact','complexity'],'Drop Landing to Stick removes both free-arm rebound coordination and immediate maximal output.','{"useWhen":["rebound_strategy_or_output_is_not_owned"],"revalidate":["identity","arm_policy","terminal_action","contacts","dose","rendering"]}'::JSONB,'review',NULL,NULL,NULL),
    (hips_variant,drop_jump_variant,'lateral_substitution',72,ARRAY['speed','complexity','impact'],'Bounce Drop Jump changes to limited flexion and shortest useful contact with reactive-strength emphasis; use only when the objective permits that strategy change.','{"revalidate":["objective","contact_strategy","primary_metric","platform_height","dose","measurement","rendering"]}'::JSONB,'review',NULL,NULL,NULL),
    (free_arms_variant,drop_jump_variant,'lateral_substitution',70,ARRAY['speed','complexity','impact'],'Bounce Drop Jump changes arm and contact strategy, primary metric, and expected rebound; it is not a silent substitution.','{"revalidate":["objective","arm_policy","contact_strategy","primary_metric","platform_height","dose","measurement","rendering"]}'::JSONB,'review',NULL,NULL,NULL)
  ON CONFLICT(from_variant_id,to_variant_id,relationship) DO UPDATE SET similarity_score=EXCLUDED.similarity_score,dimensions=EXCLUDED.dimensions,reason=EXCLUDED.reason,conditions_json=EXCLUDED.conditions_json,review_status='review',created_by=NULL,reviewed_by=NULL,reviewed_at=NULL,updated_at=now()
  WHERE coaching.exercise_relationship_v1.reviewed_by IS NULL AND coaching.exercise_relationship_v1.review_status<>'approved';

  INSERT INTO coaching.exercise_score_calibration_v1(facility_id,variant_id,dimension,proposed_score,anchor_tier,rationale,status,version,created_by,reviewed_by,review_notes,reviewed_at)
  SELECT 1,v.id,d.dimension,CASE d.dimension WHEN 'technicalComplexity' THEN v.complexity ELSE v.physical END,v.tier,
    CASE d.dimension WHEN 'technicalComplexity' THEN 'Review-only exercise-complexity anchor for platform exit, declared lead and arm policy, simultaneous contact, continuous countermovement, immediate vertical rebound, second landing, hold, and reset.' ELSE 'Review-only physical-difficulty anchor for body mass, actual fall height, surface, maximal rebound, high eccentric stress, two landings, attempts, cumulative contacts, recent lower-body exposure, symptoms, and recovery.' END||' No athlete proficiency classification is represented. Variant: '||v.variant_key||'.','review',1,NULL,NULL,NULL,NULL
  FROM (VALUES(hips_variant,'countermovement-vertical-rebound-hands-on-hips',64,72,80),(free_arms_variant,'countermovement-vertical-rebound-free-arms',68,72,80)) v(id,variant_key,complexity,physical,tier)
  CROSS JOIN (VALUES('technicalComplexity'),('absoluteLoadDemand')) d(dimension)
  ON CONFLICT(facility_id,variant_id,dimension,version) DO UPDATE SET proposed_score=EXCLUDED.proposed_score,anchor_tier=EXCLUDED.anchor_tier,rationale=EXCLUDED.rationale,status='review',created_by=NULL,reviewed_by=NULL,review_notes=NULL,reviewed_at=NULL,updated_at=now();

  UPDATE coaching.exercise SET skill_level=NULL,updated_at=now() WHERE id=ANY(source_ids);
  UPDATE coaching.exercise_safety_profile SET minimum_skill_level=NULL WHERE exercise_id=ANY(source_ids);

  INSERT INTO coaching.exercise_card_test_packet_v1(definition_id,facility_id,card_version,schema_version,audit_version,status,checks_json,blocking_issues_json,human_review_required,checked_at)
  VALUES(canonical_id,1,3,'2.0.0',migration_key,'quarantined',jsonb_build_object(
    'identity',jsonb_build_object('passed',TRUE,'legacySources',3,'activeWorkingSpecifications',2,'sourceDerivedSelectableVariants',0,'identityQuarantinedSources',source_ids),
    'taxonomy',jsonb_build_object('passed',TRUE,'controlledTerms',TRUE,'movementPatterns',jsonb_build_array('jump','land','squat','brace')),
    'anatomy',jsonb_build_object('passed',TRUE,'musclesTissuesJointsActionsPlanesAndMixedEntryBilateralReboundLaterality',TRUE,'isolatedMuscleClaim',FALSE),
    'difficulty',jsonb_build_object('passed',TRUE,'model','max_exercise_complexity_physical_difficulty','athleteProficiency',NULL,'independentCalibrationRequired',TRUE),
    'loadFatigueRecovery',jsonb_build_object('passed',TRUE,'twoLandingsPerAttempt',TRUE,'validFailedAndIncidentContacts',TRUE,'cumulativeCalfAchillesKneeHipRunningSprintJumpLiftingAndSportBudget',TRUE),
    'constraints',jsonb_build_object('passed',TRUE,'platformSurfaceCeilingStepOffFirstContactReboundFinalLandingFallReturnTrafficPopulationAndSupervision',TRUE),
    'delivery',jsonb_build_object('passed',TRUE,'profiles',4,'durationScalingDoseRestStationContactsMeasurementAndSubstitution',TRUE),
    'instructions',jsonb_build_object('passed',TRUE,'athleteCoachSupport',TRUE,'platformLeadArmsStepOffContactStrategyReboundLandingHoldResetAndStopRules',TRUE),
    'research',jsonb_build_object('passed',TRUE,'sections',16,'registryVersion',research_version,'smallTechniqueSampleAndReviewHeterogeneityExplicit',TRUE),
    'media',jsonb_build_object('passed',FALSE,'candidateCount',5,'priorOEmbedMetadataHealthy',TRUE,'freshFetchSucceeded',FALSE,'playbackReviewed',FALSE,'exactMatchReviewed',FALSE,'captionsReviewed',FALSE,'accessibilityReviewed',FALSE,'qualityReviewed',FALSE,'approvalCreated',FALSE),
    'relationships',jsonb_build_object('passed',FALSE,'reviewOnly',8,'approved',0),'calibration',jsonb_build_object('passed',FALSE,'reviewOnly',4,'approved',0),
    'alternates',jsonb_build_object('passed',TRUE,'assessments',24,'sourceIdentityQuarantines',3),
    'generationSupport',jsonb_build_object('passed',TRUE,'selectionConstraints',TRUE,'cumulativeImpactAndFatigueBudgets',TRUE,'duration',TRUE,'equipmentAndStation',TRUE,'substitutionRevalidation',TRUE,'renderingAndPersistence',TRUE),
    'publication',jsonb_build_object('passed',FALSE,'reviewer',NULL,'approver',NULL)),
    jsonb_build_array(
      jsonb_build_object('code','CARD-MEDIA-01','message','A qualified human must watch every candidate in full and verify exact hands-on-hips or free-arms variant, platform, lead, step-off, contact strategy, rebound, final landing, captions, accessibility, safety, cue quality, conflicts, reviewer identity, and current playback.'),
      jsonb_build_object('code','CARD-GRAPH-03','message','A qualified coach must approve or reject every progression, regression, and substitution proposal.'),
      jsonb_build_object('code','CARD-CALIBRATION-01','message','An independent qualified reviewer must calibrate exercise complexity and physical difficulty. These scores are not athlete proficiency.'),
      jsonb_build_object('code','CARD-PUBLISH-01','message','A qualified reviewer and separate approver must complete content review before publication. All three legacy source cards require authoritative exact specifications before source-derived restoration.')),TRUE,now())
  ON CONFLICT(definition_id) DO UPDATE SET facility_id=EXCLUDED.facility_id,card_version=EXCLUDED.card_version,schema_version=EXCLUDED.schema_version,audit_version=EXCLUDED.audit_version,status='quarantined',checks_json=EXCLUDED.checks_json,blocking_issues_json=EXCLUDED.blocking_issues_json,human_review_required=TRUE,checked_at=now();

  IF (SELECT count(*) FROM coaching.exercise_definition_source_v1 WHERE definition_id=canonical_id AND legacy_exercise_id=ANY(source_ids) AND provenance_json->>'sourceDisposition'='identity_quarantine')<>3
    OR (SELECT count(*) FROM coaching.exercise_variant_v1 WHERE id=ANY(source_variant_ids) AND definition_id=canonical_id AND status='archived' AND requirements_json->>'representation'='identity_quarantine')<>3
    OR (SELECT count(*) FROM coaching.exercise_variant_v1 WHERE id=ANY(active_variant_ids) AND definition_id=canonical_id AND status='review' AND requirements_json->>'selectable'='true' AND difficulty_json->>'technicalMeaning'='exercise_complexity' AND difficulty_json->>'loadMeaning'='physical_difficulty' AND (difficulty_json->>'baseOverallDifficulty')::INTEGER=GREATEST((difficulty_json->>'technicalComplexity')::INTEGER,(difficulty_json->>'physicalDifficulty')::INTEGER))<>2 THEN
    RAISE EXCEPTION '% found invalid source quarantine or working specifications',migration_key;
  END IF;
  IF (SELECT count(*) FROM coaching.exercise_delivery_profile_v1 WHERE variant_id=ANY(active_variant_ids) AND status='review' AND cardinality(equipment_required)>0 AND coalesce(time_model_json->>'durationFormula','')<>'' AND length(coach_instructions)>=100 AND length(athlete_instructions) BETWEEN 10 AND 240 AND cardinality(stop_rules)>=10)<>4
    OR (SELECT count(DISTINCT section_key) FROM coaching.exercise_section_evidence_v1 WHERE definition_id=canonical_id AND reviewed_card_version=3 AND review_status='candidate' AND reviewer_user_id IS NULL)<>16
    OR (SELECT count(*) FROM coaching.exercise_media_candidate_v1 WHERE definition_id=canonical_id AND reviewed_card_version=3 AND video_id=ANY(current_video_ids) AND link_status='healthy' AND review_status='candidate' AND embedding_allowed AND captions_available IS NULL AND exact_variant_match IS NULL AND demonstration_quality_score IS NULL AND reviewer_user_id IS NULL AND reviewed_at IS NULL)<>5
    OR (SELECT count(*) FROM coaching.exercise_alternate_assessment_v1 WHERE definition_id=canonical_id AND reviewed_card_version=3 AND review_status='candidate' AND reviewer_user_id IS NULL)<>24 THEN
    RAISE EXCEPTION '% found incomplete profiles, evidence, media, or alternates',migration_key;
  END IF;
  IF (SELECT count(*) FROM coaching.exercise_relationship_v1 WHERE from_variant_id=ANY(active_variant_ids) AND review_status='review' AND reviewed_by IS NULL)<>8
    OR (SELECT count(*) FROM coaching.exercise_score_calibration_v1 WHERE variant_id=ANY(active_variant_ids) AND status='review' AND version=1 AND reviewed_by IS NULL)<>4 THEN
    RAISE EXCEPTION '% found incomplete graph or calibration proposals',migration_key;
  END IF;
  IF EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 d CROSS JOIN LATERAL unnest(d.movement_patterns) key WHERE d.id=canonical_id AND NOT EXISTS(SELECT 1 FROM coaching.movement_pattern a WHERE a.key=key))
    OR EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 d CROSS JOIN LATERAL unnest(d.body_regions) key WHERE d.id=canonical_id AND NOT EXISTS(SELECT 1 FROM coaching.body_region a WHERE a.key=key))
    OR EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 d CROSS JOIN LATERAL unnest(d.required_equipment||d.optional_equipment) key WHERE d.id=canonical_id AND NOT EXISTS(SELECT 1 FROM coaching.equipment a WHERE a.key=key))
    OR EXISTS(SELECT 1 FROM coaching.exercise_relationship_v1 r WHERE r.from_variant_id=ANY(active_variant_ids) AND r.relationship IN('progression','regression') AND EXISTS(SELECT 1 FROM unnest(r.dimensions) dimension WHERE dimension<>ALL(ARRAY['load','leverage','range','speed','stability','complexity','impact','decision_demand','fatigue']))) THEN
    RAISE EXCEPTION '% created uncontrolled taxonomy or graph dimensions',migration_key;
  END IF;
  IF EXISTS(SELECT 1 FROM coaching.exercise WHERE id=ANY(source_ids) AND skill_level IS NOT NULL)
    OR EXISTS(SELECT 1 FROM coaching.exercise_safety_profile WHERE exercise_id=ANY(source_ids) AND minimum_skill_level IS NOT NULL)
    OR EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 WHERE id=canonical_id AND (reviewed_by IS NOT NULL OR approved_by IS NOT NULL OR last_reviewed_at IS NOT NULL OR approved_video_url IS NOT NULL))
    OR EXISTS(SELECT 1 FROM coaching.exercise_media_candidate_v1 WHERE definition_id=canonical_id AND reviewed_card_version=3 AND (review_status IN('approved') OR reviewer_user_id IS NOT NULL OR reviewed_at IS NOT NULL OR captions_available IS NOT NULL OR exact_variant_match IS NOT NULL OR demonstration_quality_score IS NOT NULL))
    OR EXISTS(SELECT 1 FROM coaching.exercise_card_test_packet_v1 WHERE definition_id=canonical_id AND (status<>'quarantined' OR human_review_required<>TRUE OR jsonb_array_length(blocking_issues_json)<>4)) THEN
    RAISE EXCEPTION '% fabricated proficiency, approval, or publication state',migration_key;
  END IF;
END;
$$;
